from scipy.optimize import least_squares
y = dv_dt
def base(p):
    a,b,c1,d,e = p[:5]
    return a*(x/(1+b*x))*v + c1*np.sin(d*np.sqrt(t)) + e*t*np.log(t)*x**1.5
cands4 = {
 'x': lambda: x, 'x3': lambda: x**3, 'x2':lambda: x**2, 'xv2': lambda: x*v**2, 'v2':lambda: v**2,
 'v':lambda: v, 'xv':lambda: x*v, 'x2v':lambda: x**2*v, 'xsqrtv':lambda: x*np.sqrt(v), 'cosx': lambda: np.cos(x), 'sinx': lambda: np.sin(x), 'expv': lambda: np.exp(-v), 'vabsv': lambda: v*np.abs(v), 'tv': lambda: t*v, 'x1.5': lambda: x**1.5,
}
best=None
for name,fn in cands4.items():
    F = fn()
    def res(p):
        return base(p) + p[5]*F - y
    bestr=None
    for s in range(6):
        p0 = np.random.RandomState(s).uniform(-2,2,6)
        p0[1]=abs(p0[1])
        try:
            r = least_squares(res,p0)
        except Exception:
            continue
        if bestr is None or r.cost<bestr.cost: bestr=r
    nm = np.mean(bestr.fun**2)/np.var(y)
